/**
 * AspectCategoryRef — a typed handle to an existing aspect category on
 * the Elementum platform. Distinct from {@link AppCategory} (in
 * `app.ts`), which is the by-name shape that `app({ category })`
 * accepts because the compose endpoint upserts categories by name.
 *
 * Some antman endpoints (notably `POST /v1/elements`) accept a
 * category by id only — there's no upsert there. Authors get the id
 * via `elementum list categories` (a pass-through to `ei categories list`) and import a typed handle
 * here, mirroring the `CloudLink` / `AiProviderConnector` pattern.
 *
 * ```ts
 *   // connectors/categories.ts
 *   export const importedData = category({
 *     id: "3b7a6ef4-...",
 *     name: "Imported Data",
 *   });
 *
 *   // elements/tickets.ts
 *   import { importedData } from "../connectors/categories.js";
 *
 *   element({
 *     handle: "ORDERS",
 *     category: importedData,
 *     // ...
 *   });
 * ```
 */
export interface AspectCategoryRef {
    readonly id: string;
    readonly name?: string;
}
export declare function category(opts: {
    id: string;
    name?: string;
}): AspectCategoryRef;
